const seen = new Set();

function normalizeText(text) {
  return text.toLowerCase()
    .trim()
    .replace(/[^\w\s]/g, '') // Remove special characters
    .replace(/\s+/g, ' ');   // Normalize whitespace
}

return items.filter(item => {
  const job = item.json;

  // Extract with fallbacks and normalize
  const title = normalizeText(
    job.title || job.jobTitle || job.job_title || job.name || 
    job.position || job.positionTitle || job.role || job.jobName ||
    job.job?.title || ''
  );

  const company = normalizeText(
    job.company || job.companyName || job.company_name || 
    job.employer || job.organization || job.job?.company || ''
  );

  const description = normalizeText(
    (job.description || job.jobDescription || job.job_description || 
     job.summary || job.details || job.job?.description || '')
    .substring(0, 100)
  );

  // Skip if we don't have enough data to create a meaningful key
  if (!title && !company) {
    return true; // Keep items we can't properly identify
  }

  const key = `${title}-${company}-${description}`;

  if (seen.has(key)) {
    return false;
  }
  seen.add(key);
  return true;
});

