// This code filters for successful jobs, then aggregates them into a single email.

// 1. Filter the incoming items to only include jobs that were successfully processed in the loop.
const successfulJobs = items.filter(item => 
  item.json.tailored_resume && item.json.cover_letter
);

// 2. Handle the case where ALL jobs failed or were filtered out.
if (successfulJobs.length === 0) {
  const initialData = $('On form submission').item.json;
  return [{
    json: {
      status: 'failure',
      reason: 'No jobs were successfully processed. This could be due to a low resume match score or an error during generation.',
      userEmail: initialData.Email,
      userName: initialData['Full Name']
    }
  }];
}

// 3. If we have successful jobs, get the user's details from the first one.
const userData = successfulJobs[0].json;
const userName = userData['Full Name'];
const userEmail = userData.Email;

// 4. Start building the single HTML email.
let emailHtml = `
<html>
  <body style="font-family: Arial, sans-serif; line-height: 1.6; color: #333;">
    <p>Hi ${userName},</p>
    <p>Your JobMonkey request is complete! Here are the tailored resumes and cover letters for the ${successfulJobs.length} job(s) that were successfully processed:</p>
`;

// 5. Loop through ONLY the successful jobs and add their details.
let jobCounter = 1;
for (const item of successfulJobs) {
  const jobData = item.json;
  emailHtml += `
    <hr style="margin: 30px 0; border: 1px solid #ccc;">
    <h2>Job #${jobCounter}: ${jobData.job_title} at ${jobData.company_name}</h2>
    <p><strong>Job URL:</strong> <a href="${jobData.job_url}" target="_blank">${jobData.job_url}</a></p>

    <h3>Your Custom Cover Letter:</h3>
    <div style="background: #f9f9f9; padding: 15px; border: 1px solid #eee; border-radius: 8px; margin-bottom: 15px;">
      ${jobData.cover_letter}
    </div>

    <h3>Your Tailored Resume:</h3>
    <div style="background: #f9f9f9; padding: 15px; border: 1px solid #eee; border-radius: 8px;">
      ${jobData.tailored_resume}
    </div>
  `;
  jobCounter++;
}

// 6. Add the closing part of the email.
emailHtml += `
    <hr style="margin-top: 30px;">
    <p>Good luck with your applications!</p>
    <p>The JobMonkey Team</p>
  </body>
</html>
`;

// 7. Return the final, single data packet for the email node.
return [{
  json: {
    finalEmailBody: emailHtml,
    userEmail: userEmail,
    userName: userName,
    status: 'success'
  }
}];

// Set the maximum number of jobs you want to process.
const maxJobs = 10;

// This line takes the full list of jobs and returns only the first 15.
return items.slice(0, maxJobs);

