add_shortcode('interview_app', 'interview_app_render_container');

/**
 * Renders the main container for the interview app.
 *
 * This function now checks if the user is logged in. If not, it displays a
 * login prompt. If they are, it proceeds with rendering the app container.
 */
function interview_app_render_container() {
    // Check if the user is logged in.
    if (!is_user_logged_in()) {
        ob_start();
        ?>
        <div id="interview-app-container" style="text-align: center; padding: 40px; background-color: #f9f9f9; border: 1px solid #ddd; border-radius: 8px;">
            <h2>You must be logged in to use this feature.</h2>
            <p>Please <a href="<?php echo wp_login_url(get_permalink()); ?>">log in</a> to continue.</p>
        </div>
        <?php
        return ob_get_clean();
    }

    // If the user is logged in, proceed with rendering the app.
    $nonce = wp_create_nonce('interview_app_nonce_v4');
    ob_start();
    ?>
    <style>
        #interview-app-container { border: 1px solid #ddd; padding: 20px; border-radius: 8px; background-color: #f9f9f9; min-height: 500px; position: relative; }
        .interview-tool-loader { position: absolute; top: 50%; left: 50%; transform: translate(-50%, -50%); font-size: 1.2em; color: #555; }
        .interview-tool-start-button-wrapper { text-align: center; padding: 40px 20px; }
        #interview-tool-begin-btn { display: inline-block; padding: 15px 30px; border: none; background-color: #2a7c4f; color: #fff; font-size: 1.2em; border-radius: 5px; cursor: pointer; transition: background-color 0.3s; }
        #interview-tool-begin-btn:hover { background-color: #1e5a39; }
        /* Styles from n8n workflow */
        #interview-app-container .container { background-color: #ffffff; text-align: left; padding: 16px; border-radius: 8px; }
        #interview-app-container .msg { padding: 5px; background-color: #eee; margin-bottom: 5px; border-radius: 4px; }
        #interview-app-container .msgUsr { padding: 5px; background-color: #e4eefd; margin-bottom: 5px; border-radius: 4px; }
        #interview-app-container .curMsg { padding: 5px; background-color: #e6ffd9; min-height: 24px; border-radius: 4px; }
        #interview-app-container h1 { margin: 5px; font-size: 20px; }
    </style>
    <div id="interview-app-container">
        <div class="interview-tool-loader">Loading Interview Setup...</div>
    </div>
    <script type="text/javascript">
        document.addEventListener('DOMContentLoaded', function() {
            const container = document.getElementById('interview-app-container');
            const ajax_url = '<?php echo admin_url('admin-ajax.php'); ?>';
            const nonce = '<?php echo $nonce; ?>';

            // --- Core Interview Logic ---
            function startTimer(duration, display) {
                let timer = duration * 60, minutes, seconds;
                const interval = setInterval(function () {
                    minutes = parseInt(timer / 60, 10);
                    seconds = parseInt(timer % 60, 10);
                    minutes = minutes < 10 ? "0" + minutes : minutes;
                    seconds = seconds < 10 ? "0" + seconds : seconds;
                    if(display) display.textContent = "Time Remaining: " + minutes + ":" + seconds;
                    if (--timer < 0) {
                        clearInterval(interval);
                        if(display) display.textContent = "Time's up! Finalizing...";
                        const finishButton = container.querySelector('#finishButton');
                        if(finishButton) finishButton.click();
                    }
                }, 1000);
            }

            function handleResponse(e) {
                var obj = JSON.parse(e.data);
                const messagesContainer = container.querySelector('.messages');
                const currentMsgContainer = container.querySelector('.curMsg');
                if (!messagesContainer || !currentMsgContainer) return;
                if (obj.type == 'response.audio_transcript.done') {
                    currentMsgContainer.innerHTML = "";
                    messagesContainer.innerHTML += "<div class='msg'><b>AI:</b> " + obj.transcript + "</div>";
                } else if (obj.type == 'conversation.item.input_audio_transcription.completed') {
                    currentMsgContainer.innerHTML = "";
                    messagesContainer.innerHTML += "<div class='msgUsr'><b>User:</b> " + obj.transcript + "</div>";
                } else if (obj.type == 'response.audio_transcript.delta' || obj.type == 'conversation.item.input_audio_transcription.delta') {
                    currentMsgContainer.innerHTML += obj.delta;
                }
                messagesContainer.scrollTop = messagesContainer.scrollHeight;
            }

            async function initInterviewSession(ephemeralKey) {
                try {
                    const pc = new RTCPeerConnection();
                    const audioEl = document.createElement("audio");
                    audioEl.autoplay = true;
                    pc.ontrack = e => audioEl.srcObject = e.streams[0];
                    const ms = await navigator.mediaDevices.getUserMedia({ audio: true });
                    pc.addTrack(ms.getTracks()[0]);
                    const dc = pc.createDataChannel("oai-events");
                    dc.addEventListener("message", handleResponse);
                    const offer = await pc.createOffer();
                    await pc.setLocalDescription(offer);
                    const sdpResponse = await fetch(`https://api.openai.com/v1/realtime?model=gpt-4o-realtime-preview-2024-12-17`, {
                        method: "POST",
                        body: offer.sdp,
                        headers: { Authorization: `Bearer ${ephemeralKey}`, "Content-Type": "application/sdp" },
                    });
                    const answer = { type: "answer", sdp: await sdpResponse.text() };
                    await pc.setRemoteDescription(answer);
                    startTimer(15, container.querySelector('#timer'));
                } catch (err) {
                    console.error("WebRTC Initialization Error:", err);
                    container.innerHTML = `<p>A critical error occurred: Could not connect to the real-time audio service. Please ensure your browser has microphone permissions and is not blocking WebRTC.</p>`;
                }
            }

            // --- Application Flow ---
            container.addEventListener('click', function(event) {
                if (event.target && event.target.id === 'finishButton') {
                    const finishButton = event.target;
                    const messagesDiv = container.querySelector('.messages');
                    const transcript = messagesDiv ? messagesDiv.innerText : 'No transcript found.';
                    const userEmail = container.dataset.userEmail || '';
                    finishButton.disabled = true;
                    finishButton.innerText = "Finalizing... Redirecting...";
                    localStorage.setItem('interviewTranscript', transcript);
                    localStorage.setItem('interviewUserEmail', userEmail);

                    window.location.href = 'https://jobmonkey.dev/mock-interview-report/'; // CHANGE THIS URL
                }
            });

            async function makeAjaxRequest(action, data = {}) {
                const formData = new FormData();
                formData.append('action', action);
                formData.append('nonce', nonce);
                for (const key in data) formData.append(key, data[key]);
                const response = await fetch(ajax_url, { method: 'POST', body: formData });
                if (!response.ok) throw new Error(`HTTP error! Status: ${response.status}`);
                return await response.json();
            }

            async function loadSetupForm() {
                const response = await makeAjaxRequest('interview_app_get_setup_form_v4');
                if (response.success) {
                    container.innerHTML = response.data;
                    const form = container.querySelector('form');
                    if (form) form.addEventListener('submit', handleFormSubmit);
                } else {
                    container.innerHTML = response.data;
                }
            }

            async function handleFormSubmit(event) {
                event.preventDefault();
                container.innerHTML = '<div class="interview-tool-loader">Preparing your interview...</div>';
                const formData = new FormData(event.target);
                const data = {
                    jobRole: formData.get('jobRole'),
                    userEmail: formData.get('userEmail'),
                    resumeText: formData.get('resumeText'),
                };
                const response = await makeAjaxRequest('interview_app_start_interview_v4', data);
                if (response.success) {
                    prepareInterviewInterface(response.data.html, response.data.key, data.userEmail);
                } else {
                    container.innerHTML = response.data;
                }
            }

            function prepareInterviewInterface(interviewHTML, ephemeralKey, userEmail) {
                const startButtonHTML = `<div class="interview-tool-start-button-wrapper"><h2>Your interview is ready.</h2><p>Click the button below to begin. This will activate your microphone.</p><button id="interview-tool-begin-btn">Begin Interview</button></div>`;
                container.innerHTML = startButtonHTML;
                const interviewUI = document.createElement('div');
                interviewUI.innerHTML = interviewHTML;
                interviewUI.style.display = 'none';
                container.appendChild(interviewUI);
                container.dataset.userEmail = userEmail; // Store email for the finish button
                document.getElementById('interview-tool-begin-btn').addEventListener('click', () => {
                    document.querySelector('.interview-tool-start-button-wrapper').style.display = 'none';
                    interviewUI.style.display = 'block';
                    initInterviewSession(ephemeralKey);
                });
            }

            loadSetupForm();
        });
    </script>
    <?php
    return ob_get_clean();
}

// AJAX Handlers for Snippet 1
add_action('wp_ajax_interview_app_get_setup_form_v4', 'interview_app_get_setup_form_handler_v4');
add_action('wp_ajax_interview_app_start_interview_v4', 'interview_app_start_interview_handler_v4');

/**
 * AJAX handler to get the interview setup form.
 * Only runs if the user is logged in.
 */
function interview_app_get_setup_form_handler_v4() {
    // Check for user login and nonce.
    if (!is_user_logged_in()) {
        wp_send_json_error('<p>You must be logged in to access this feature.</p>');
        return;
    }
    check_ajax_referer('interview_app_nonce_v4', 'nonce');

    $response = wp_remote_get('https://n8n.dominixai.com/webhook/interview-setup');

    if (is_wp_error($response)) {
        wp_send_json_error('<p>Could not load setup form.</p>');
    } else {
        wp_send_json_success(wp_remote_retrieve_body($response));
    }
}

/**
 * AJAX handler to start the interview session.
 * Only runs if the user is logged in.
 */
function interview_app_start_interview_handler_v4() {
    // Check for user login and nonce.
    if (!is_user_logged_in()) {
        wp_send_json_error('<p>You must be logged in to access this feature.</p>');
        return;
    }
    check_ajax_referer('interview_app_nonce_v4', 'nonce');

    $args = [
        'body' => [
            'jobRole'    => sanitize_text_field($_POST['jobRole']),
            'userEmail'  => sanitize_email($_POST['userEmail']),
            'resumeText' => sanitize_textarea_field($_POST['resumeText']),
        ],
        'timeout' => 20,
    ];

    $response = wp_remote_post('https://n8n.dominixai.com/webhook/start-interview', $args);

    if (is_wp_error($response)) {
        wp_send_json_error('<p>Could not start interview session.</p>');
        return;
    }

    $body = wp_remote_retrieve_body($response);

    // Extract the ephemeral key and the clean HTML from the response
    $ephemeral_key = '';
    $interview_html = '';
    if (class_exists('DOMDocument')) {
        $doc = new DOMDocument();
        // Suppress warnings from potentially malformed HTML from the webhook
        @$doc->loadHTML($body);
        $script_tags = $doc->getElementsByTagName('script');

        if ($script_tags->length > 0) {
            $script_content = $script_tags->item(0)->nodeValue;
            // Use regex to find: const EPHEMERAL_KEY = "some_key_here";
            preg_match('/const EPHEMERAL_KEY = "(.*?)";/', $script_content, $matches);
            if (isset($matches[1])) {
                $ephemeral_key = $matches[1];
            }
            // Remove the script tag to get clean HTML for the UI
            $script_tags->item(0)->parentNode->removeChild($script_tags->item(0));
        }
        $interview_html_node = $doc->getElementsByTagName('body')->item(0);
        $interview_html = $interview_html_node ? $doc->saveHTML($interview_html_node) : '';
    }

    if (empty($ephemeral_key) || empty($interview_html)) {
        wp_send_json_error('<p>Error: The interview service response was invalid. Could not extract session key.</p>');
    } else {
        wp_send_json_success([
            'html' => $interview_html,
            'key'  => $ephemeral_key,
        ]);
    }
}

