// Get the combined text from the previous AI node
const fullOutput = $json.output;
const resumeMarker = '### REWRITTEN RESUME ###';
const coverLetterMarker = '### COVER LETTER ###';

// Find the starting position of each section
const resumeStartIndex = fullOutput.indexOf(resumeMarker);
const coverLetterStartIndex = fullOutput.indexOf(coverLetterMarker);

let parsedResume = 'Error: Could not parse resume from AI output.';
let parsedCoverLetter = 'Error: Could not parse cover letter from AI output.';

// Extract the text for each section if the markers are found
if (resumeStartIndex !== -1 && coverLetterStartIndex !== -1) {
  parsedResume = fullOutput.substring(resumeStartIndex + resumeMarker.length, coverLetterStartIndex).trim();
  parsedCoverLetter = fullOutput.substring(coverLetterStartIndex + coverLetterMarker.length).trim();
}

// Get all the original data from the start of the loop
const originalData = $('Loop Over Items').item.json;

// Return the original data with the two new, separated fields
return [{
  json: {
    ...originalData,
    tailored_resume: parsedResume,
    cover_letter: parsedCoverLetter,
  }
}];
